package ca.team.originkickoff;

import android.content.Intent;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.adapter.FragmentStateAdapter;
import androidx.viewpager2.widget.ViewPager2;

import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;
import com.google.firebase.firestore.FirebaseFirestore;

import androidx.appcompat.widget.Toolbar;

import ca.team.originkickoff.util.DeviceUtils;

public class MyEventsActivity extends AppCompatActivity {
    private static final String TAG = "MyEventsActivity";
    private TabLayout tabLayout;
    private ViewPager2 viewPager;
    private boolean isOrganizer = false;
    private FirebaseFirestore db;

    // Debounce for bottom-nav taps
    private long lastNavTapAtMs = 0L;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_my_events);

        Toolbar toolbar = findViewById(R.id.toolbar);
        if (toolbar != null) {
            setSupportActionBar(toolbar);
        }

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
            getSupportActionBar().setTitle("My Events");
        }

        db = FirebaseFirestore.getInstance();
        tabLayout = findViewById(R.id.tabLayout);
        viewPager = findViewById(R.id.viewPager);

        // Check if user is an organizer first, then setup tabs
        checkIfUserIsOrganizer();

        // Setup bottom navigation include
        setupBottomNav();
    }

    private void checkIfUserIsOrganizer() {
        String deviceId = DeviceUtils.getDeviceId(this);
        if (deviceId == null) {
            Log.w(TAG, "Device ID is null, defaulting to non-organizer");
            setupTabs(false);
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(queryDocumentSnapshots -> {
                    if (!queryDocumentSnapshots.isEmpty()) {
                        Boolean isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                        isOrganizer = isOrganizerField != null && isOrganizerField;
                        Log.d(TAG, "User is organizer: " + isOrganizer);
                    } else {
                        Log.w(TAG, "No user found for device_id");
                        isOrganizer = false;
                    }
                    setupTabs(isOrganizer);
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error checking organizer status", e);
                    isOrganizer = false;
                    setupTabs(false);
                });
    }

    private void setupTabs(boolean showOrganizerTab) {
        // Create adapter with dynamic tab count
        viewPager.setAdapter(new FragmentStateAdapter(this) {
            @NonNull
            @Override
            public Fragment createFragment(int position) {
                if (!showOrganizerTab) {
                    // Only show Events Joined
                    return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                } else {
                    // Show both tabs
                    if (position == 0) {
                        return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                    } else {
                        return new ca.team.originkickoff.ui.fragments.EventsOrganizedFragment();
                    }
                }
            }

            @Override
            public int getItemCount() {
                return showOrganizerTab ? 2 : 1;
            }
        });

        // Setup tab names
        new TabLayoutMediator(tabLayout, viewPager, (tab, position) -> {
            if (!showOrganizerTab) {
                // Only one tab
                tab.setText("Events Joined");
            } else {
                // Two tabs
                if (position == 0) {
                    tab.setText("Events Joined");
                } else {
                    tab.setText("Events Organized");
                }
            }
        }).attach();

        // Wire FAB: only visible for organizers on Events Organized tab (index 1)
        FloatingActionButton fab = findViewById(R.id.fabCreate);
        if (fab != null && showOrganizerTab) {
            fab.setOnClickListener(v -> startActivity(new Intent(MyEventsActivity.this, CreateEventActivity.class)));

            // initial visibility
            fab.setVisibility(viewPager.getCurrentItem() == 1 ? View.VISIBLE : View.GONE);

            // show/hide based on page
            viewPager.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback() {
                @Override
                public void onPageSelected(int position) {
                    super.onPageSelected(position);
                    if (position == 1) fab.setVisibility(View.VISIBLE);
                    else fab.setVisibility(View.GONE);
                }
            });
        } else if (fab != null) {
            // Hide FAB completely for non-organizers
            fab.setVisibility(View.GONE);
        }
    }

    private void setupBottomNav() {
        LinearLayout navHome = findViewById(R.id.navHome);
        LinearLayout navEvents = findViewById(R.id.navEvents);
        LinearLayout navNotifications = findViewById(R.id.navNotifications);
        LinearLayout navProfile = findViewById(R.id.navProfile);

        if (navHome == null || navEvents == null || navNotifications == null || navProfile == null) return;

        // Highlight current tab (My Events)
        ImageView ivEvents = findViewById(R.id.ivEvents);
        TextView tvEvents = findViewById(R.id.tvEvents);
        if (ivEvents != null) ivEvents.setColorFilter(0xFF00D9C5, android.graphics.PorterDuff.Mode.SRC_IN);
        if (tvEvents != null) tvEvents.setTextColor(0xFF00D9C5);

        navHome.setOnClickListener(v -> navigateBottomTab(MainActivity.class));
        navEvents.setOnClickListener(v -> { /* already here */ });
        navNotifications.setOnClickListener(v -> navigateBottomTab(NotificationsActivity.class));
        navProfile.setOnClickListener(v -> navigateBottomTab(ProfileActivity.class));
    }

    // Helper to navigate between bottom-bar destinations smoothly with no transition animation
    private void navigateBottomTab(Class<?> targetActivity) {
        if (targetActivity == null) return;
        if (getClass().equals(targetActivity)) return; // already on this tab
        long now = SystemClock.elapsedRealtime();
        if (now - lastNavTapAtMs < 300) return; // debounce rapid taps
        lastNavTapAtMs = now;
        Intent intent = new Intent(this, targetActivity);
        intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_NO_ANIMATION);
        startActivity(intent);
        overridePendingTransition(0, 0);
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }
}

package ca.team.originkickoff;

import android.content.Intent;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.adapter.FragmentStateAdapter;
import androidx.viewpager2.widget.ViewPager2;

import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;
import com.google.firebase.firestore.FirebaseFirestore;

import androidx.appcompat.widget.Toolbar;

import ca.team.originkickoff.util.DeviceUtils;

public class MyEventsActivity extends AppCompatActivity {
    private static final String TAG = "MyEventsActivity";
    private TabLayout tabLayout;
    private ViewPager2 viewPager;
    private boolean isOrganizer = false;
    private FirebaseFirestore db;

    // Debounce for bottom-nav taps
    private long lastNavTapAtMs = 0L;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_my_events);

        Toolbar toolbar = findViewById(R.id.toolbar);
        if (toolbar != null) {
            setSupportActionBar(toolbar);
        }

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
            getSupportActionBar().setTitle("My Events");
        }

        db = FirebaseFirestore.getInstance();
        tabLayout = findViewById(R.id.tabLayout);
        viewPager = findViewById(R.id.viewPager);

        // Check if user is an organizer first, then setup tabs
        checkIfUserIsOrganizer();

        // Setup bottom navigation include
        setupBottomNav();
    }

    private void checkIfUserIsOrganizer() {
        String deviceId = DeviceUtils.getDeviceId(this);
        if (deviceId == null) {
            Log.w(TAG, "Device ID is null, defaulting to non-organizer");
            setupTabs(false);
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(queryDocumentSnapshots -> {
                    if (!queryDocumentSnapshots.isEmpty()) {
                        Boolean isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                        if (isOrganizerField == null) isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organiser");
                        if (isOrganizerField == null) {
                            Object camel = queryDocumentSnapshots.getDocuments().get(0).get("isOrganizer");
                            if (camel instanceof Boolean) isOrganizerField = (Boolean) camel;
                        }
                        isOrganizer = isOrganizerField != null && isOrganizerField;
                        Log.d(TAG, "User explicit organizer flag: " + isOrganizer);

                        if (!isOrganizer) {
                            // Fallback inference: does user have any events with organizerId == their document ID or deviceId?
                            String userDocId = queryDocumentSnapshots.getDocuments().get(0).getId();
                            java.util.List<String> possibleIds = new java.util.ArrayList<>();
                            possibleIds.add(userDocId);
                            if (!deviceId.equals(userDocId)) possibleIds.add(deviceId);
                            db.collection("events")
                                    .whereIn("organizerId", possibleIds)
                                    .limit(1)
                                    .get()
                                    .addOnSuccessListener(evSnap -> {
                                        if (!evSnap.isEmpty()) {
                                            Log.d(TAG, "Inferred organizer via existing events");
                                            isOrganizer = true;
                                        }
                                        setupTabs(isOrganizer);
                                    })
                                    .addOnFailureListener(e -> {
                                        Log.e(TAG, "Organizer inference failed", e);
                                        setupTabs(isOrganizer);
                                    });
                        } else {
                            setupTabs(true);
                        }
                    } else {
                        Log.w(TAG, "No user found for device_id");
                        isOrganizer = false;
                        setupTabs(false);
                    }
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error checking organizer status", e);
                    isOrganizer = false;
                    setupTabs(false);
                });
    }

    private void setupTabs(boolean showOrganizerTab) {
        // Create adapter with dynamic tab count
        viewPager.setAdapter(new FragmentStateAdapter(this) {
            @NonNull
            @Override
            public Fragment createFragment(int position) {
                if (!showOrganizerTab) {
                    // Only show Events Joined
                    return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                } else {
                    // Show both tabs
                    if (position == 0) {
                        return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                    } else {
                        return new ca.team.originkickoff.ui.fragments.EventsOrganizedFragment();
                    }
                }
            }

            @Override
            public int getItemCount() {
                return showOrganizerTab ? 2 : 1;
            }
        });

        // Setup tab names
        new TabLayoutMediator(tabLayout, viewPager, (tab, position) -> {
            if (!showOrganizerTab) {
                // Only one tab
                tab.setText("Events Joined");
            } else {
                // Two tabs
                if (position == 0) {
                    tab.setText("Events Joined");
                } else {
                    tab.setText("Events Organized");
                }
            }
        }).attach();

        // Wire FAB: only visible for organizers on Events Organized tab (index 1)
        FloatingActionButton fab = findViewById(R.id.fabCreate);
        if (fab != null && showOrganizerTab) {
            fab.setOnClickListener(v -> startActivity(new Intent(MyEventsActivity.this, CreateEventActivity.class)));

            // initial visibility
            fab.setVisibility(viewPager.getCurrentItem() == 1 ? View.VISIBLE : View.GONE);

            // show/hide based on page
            viewPager.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback() {
                @Override
                public void onPageSelected(int position) {
                    super.onPageSelected(position);
                    if (position == 1) fab.setVisibility(View.VISIBLE);
                    else fab.setVisibility(View.GONE);
                }
            });
        } else if (fab != null) {
            // Hide FAB completely for non-organizers
            fab.setVisibility(View.GONE);
        }
    }

    private void setupBottomNav() {
        LinearLayout navHome = findViewById(R.id.navHome);
        LinearLayout navEvents = findViewById(R.id.navEvents);
        LinearLayout navNotifications = findViewById(R.id.navNotifications);
        LinearLayout navProfile = findViewById(R.id.navProfile);

        if (navHome == null || navEvents == null || navNotifications == null || navProfile == null) return;

        // Highlight current tab (My Events)
        ImageView ivEvents = findViewById(R.id.ivEvents);
        TextView tvEvents = findViewById(R.id.tvEvents);
        if (ivEvents != null) ivEvents.setColorFilter(0xFF00D9C5, android.graphics.PorterDuff.Mode.SRC_IN);
        if (tvEvents != null) tvEvents.setTextColor(0xFF00D9C5);

        navHome.setOnClickListener(v -> navigateBottomTab(MainActivity.class));
        navEvents.setOnClickListener(v -> { /* already here */ });
        navNotifications.setOnClickListener(v -> navigateBottomTab(NotificationsActivity.class));
        navProfile.setOnClickListener(v -> navigateBottomTab(ProfileActivity.class));
    }

    // Helper to navigate between bottom-bar destinations smoothly with no transition animation
    private void navigateBottomTab(Class<?> targetActivity) {
        if (targetActivity == null) return;
        if (getClass().equals(targetActivity)) return; // already on this tab
        long now = SystemClock.elapsedRealtime();
        if (now - lastNavTapAtMs < 300) return; // debounce rapid taps
        lastNavTapAtMs = now;
        Intent intent = new Intent(this, targetActivity);
        intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_NO_ANIMATION);
        startActivity(intent);
        overridePendingTransition(0, 0);
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }
}

/**
 * RecyclerView adapter rendering event cards and handling click navigation.
 * Central to listing joined/available events with status and images.
 */
package ca.team.originkickoff.adapters;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.recyclerview.widget.RecyclerView;

import com.bumptech.glide.Glide;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import ca.team.originkickoff.R;
import ca.team.originkickoff.models.Event;

/**
 * Adapter that binds {@link ca.team.originkickoff.models.Event} data to item_event_card views.
 */
public class EventAdapter extends RecyclerView.Adapter<EventAdapter.EventViewHolder> {
    private List<Event> events;
    private OnEventClickListener listener;
    private java.util.Map<String, String> eventStatusMap; // For displaying lottery status

    /**
     * Listener for event card taps.
     */
    public interface OnEventClickListener {
        /**
         * Called when an event item is tapped.
         * @param event the event associated with the clicked item
         */
        void onEventClick(Event event);
    }

    /**
     * Creates an adapter with an empty list.
     * @param listener callback for click events; may be null
     */
    public EventAdapter(OnEventClickListener listener) {
        this.events = new ArrayList<>();
        this.listener = listener;
    }

    /**
     * Creates an adapter with an initial list of events.
     * @param events initial events list (nullable)
     * @param listener callback for click events; may be null
     */
    public EventAdapter(List<Event> events, OnEventClickListener listener) {
        this.events = events != null ? new ArrayList<>(events) : new ArrayList<>();
        this.listener = listener;
    }

    /**
     * Replaces the current list of events and refreshes the UI.
     * Clears any previously provided status map.
     * @param events new events list (nullable)
     */
    public void setEvents(List<Event> events) {
        this.events = events != null ? events : new ArrayList<>();
        this.eventStatusMap = null; // Clear status map when setting plain events
        notifyDataSetChanged();
    }

    /**
     * Updates events for compatibility with older callers.
     * Clears any previously provided status map.
     * @param events new events list (nullable)
     */
    public void updateEvents(List<Event> events) {
        this.events.clear();
        if (events != null) {
            this.events.addAll(events);
        }
        this.eventStatusMap = null; // Clear status map
        notifyDataSetChanged();
    }

    /**
     * Sets events together with a per-event status message to display instead of spots left.
     * @param events events to render (nullable)
     * @param statusMap map from eventId to status text (e.g., YOU WERE SELECTED)
     */
    public void setEventsWithStatus(List<Event> events, java.util.Map<String, String> statusMap) {
        this.events = events != null ? events : new ArrayList<>();
        this.eventStatusMap = statusMap;
        notifyDataSetChanged();
    }

    /**
     * Inflates and creates a new {@link EventViewHolder}.
     * @param parent the parent view group
     * @param viewType unused view type
     * @return a new view holder instance
     */
    @NonNull
    @Override
    public EventViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(parent.getContext())
                .inflate(R.layout.item_event_card, parent, false);
        return new EventViewHolder(view);
    }

    /**
     * Binds the event at the given position to the holder.
     * @param holder target view holder
     * @param position adapter position to bind
     */
    @Override
    public void onBindViewHolder(@NonNull EventViewHolder holder, int position) {
        Event event = events.get(position);
        holder.bind(event, listener, eventStatusMap);
    }

    /**
     * @return the number of events currently in the adapter
     */
    @Override
    public int getItemCount() {
        return events.size();
    }

    /**
     * ViewHolder that displays an event card and forwards click events.
     */
    static class EventViewHolder extends RecyclerView.ViewHolder {
        private final ImageView ivEventImage;
        private final TextView tvEventName;
        private final TextView tvEventDate;
        private final TextView tvSpotsLeft;
        private final TextView tvRequirements;

        /**
         * Creates a holder bound to the given item view.
         * @param itemView the inflated item view
         */
        public EventViewHolder(@NonNull View itemView) {
            super(itemView);
            ivEventImage = itemView.findViewById(R.id.ivEventImage);
            tvEventName = itemView.findViewById(R.id.tvEventName);
            tvEventDate = itemView.findViewById(R.id.tvEventDate);
            tvSpotsLeft = itemView.findViewById(R.id.tvSpotsLeft);
            tvRequirements = itemView.findViewById(R.id.tvRequirements);
        }

        /**
         * Binds view content and click behavior for an event.
         * Handles date formatting, status color coding, and image loading.
         * @param event the event to display
         * @param listener click listener (nullable)
         * @param statusMap optional map of eventId to status text for joined events
         */
        public void bind(Event event, OnEventClickListener listener, java.util.Map<String, String> statusMap) {
            tvEventName.setText(event.getName());

            // Format date
            if (event.getEventDate() != null) {
                SimpleDateFormat dateFormat = new SimpleDateFormat("MMM dd, yyyy", Locale.getDefault());
                tvEventDate.setText(dateFormat.format(event.getEventDate()));
            } else {
                tvEventDate.setText("Date TBD");
            }

            // Calculate spots left or show status if available
            if (statusMap != null && statusMap.containsKey(event.getId())) {
                // Show lottery status instead of spots left
                String status = statusMap.get(event.getId());
                tvSpotsLeft.setText(status);

                // Color code the status
                if ("YOU WERE SELECTED".equals(status)) {
                    tvSpotsLeft.setTextColor(0xFF4DE8C0); // Success green/teal
                } else if ("YOU WERE NOT SELECTED".equals(status)) {
                    tvSpotsLeft.setTextColor(0xFFFF3B30); // Red
                } else {
                    tvSpotsLeft.setTextColor(0xFFFFD60A); // Yellow for "YET TO DRAW"
                }
            } else {
                // Normal behavior - show spots left
                int spotsLeft = event.getCapacity() - event.getWaitlistCount();
                if (spotsLeft < 0) spotsLeft = 0;
                tvSpotsLeft.setText(spotsLeft + " spots left");
                tvSpotsLeft.setTextColor(0xFFFFFFFF); // White
            }

            // Show requirements
            if (event.isGeolocationRequired()) {
                tvRequirements.setText("Req: Geolocation");
            } else {
                tvRequirements.setText("");
            }

            // Set click listener
            itemView.setOnClickListener(v -> {
                if (listener != null) {
                    listener.onEventClick(event);
                }
            });

            // Load image: Base64 first, then URL fallback, else placeholder
            boolean imageSet = false;
            String b64 = event.getPosterBase64();
            if (b64 != null && !b64.isEmpty()) {
                try {
                    byte[] decoded = Base64.decode(b64, Base64.DEFAULT);
                    Bitmap bmp = BitmapFactory.decodeByteArray(decoded, 0, decoded.length);
                    if (bmp != null) {
                        ivEventImage.setImageBitmap(bmp);
                        imageSet = true;
                    }
                } catch (Exception ignored) {}
            }
            if (!imageSet) {
                String url = event.getPosterUrl();
                if (url != null && !url.isEmpty()) {
                    Glide.with(itemView.getContext())
                            .load(url)
                            .placeholder(R.drawable.sample_event_1)
                            .error(R.drawable.sample_event_1)
                            .into(ivEventImage);
                    imageSet = true;
                }
            }
            if (!imageSet) {
                ivEventImage.setImageResource(R.drawable.sample_event_1);
            }
        }
    }
}

