                                    .apply(RequestOptions.circleCropTransform())
                                    .into(ivProfilePic);
                        } catch (Exception e) {
                            showPlaceholderImage();
                        }
                    } else {
                        showPlaceholderImage();
                    }
                } else {
                    showPlaceholderImage();
                }
            }).addOnFailureListener(e -> showPlaceholderImage());
        }

        /**
         * Shows a placeholder avatar when no custom image is available.
         */
        private void showPlaceholderImage() {
